<script setup>
import { ref, computed } from 'vue';
import { ROLE_LABELS, MODULES, SECTIONS } from '../../../lib/security/roles.js';
import { ACCOUNT_STATES, MODULE_LABELS, ROLE_DESCRIPTIONS, initials } from '../../../lib/adminUi.js';
import { NEWS_SECTIONS, dateLabel, adminRequest } from '../../../lib/publicationUi.js';
const props=defineProps({initialAccount:{type:Object,default:null},viewer:{type:Object,required:true}});
const account=ref(props.initialAccount), form=ref(makeForm(props.initialAccount)), busy=ref(false), error=ref(''), notice=ref(''), setupLink=ref(''), sessionEnded=ref(false), confirmDialog=ref(null), pending=ref('');
function makeForm(user){return user?JSON.parse(JSON.stringify({name:user.name,email:user.email,status:user.status,assignments:user.assignments,version:user.authVersion})):{name:'',email:'',status:'invited',assignments:[{role:'colaborador',modules:['gaceta'],sections:['actualidad']}]};}
const isNew=computed(()=>!account.value);
const dirty=computed(()=>JSON.stringify(form.value)!==JSON.stringify(makeForm(account.value)));
const moduleCount=computed(()=>new Set(form.value.assignments.filter(a=>a.role!=='administrador').flatMap(a=>a.modules)).size);
function changeRole(a){if(a.role==='administrador'){a.modules=[];a.sections=[];}}
function toggleAll(a,event){a.sections=event.target.checked?['*']:[];}
function selectSection(a){a.sections=a.sections.filter(s=>s!=='*');}
function showLink(id,token){setupLink.value=`${location.origin}/activar-cuenta#id=${encodeURIComponent(id)}&token=${encodeURIComponent(token)}`;}
async function run(action){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function save(){await run(async()=>{
  if(form.value.assignments.some(a=>a.role!=='administrador'&&(!a.modules.length||(a.modules.includes('gaceta')&&!a.sections.length))))throw new Error('Selecciona al menos un módulo para cada rol y las secciones de Gaceta que correspondan.');
  const assignments=form.value.assignments.map(a=>({...a,modules:a.role==='administrador'?[]:a.modules,sections:a.role!=='administrador'&&a.modules.includes('gaceta')?a.sections:[]}));
  if(isNew.value){const data=await adminRequest('/api/usuarios',{method:'POST',body:JSON.stringify({name:form.value.name,email:form.value.email,assignments})});account.value=data.user;form.value=makeForm(data.user);showLink(data.user.id,data.setupToken);history.replaceState({},'',`/admin/usuarios/${data.user.id}`);notice.value='Invitación creada. Entrega el enlace a esta persona por un canal privado.';}
  else {const data=await adminRequest(`/api/usuarios/${account.value.id}`,{method:'PATCH',body:JSON.stringify({name:form.value.name,status:form.value.status,assignments,version:form.value.version})});account.value=data.user;form.value=makeForm(data.user);notice.value='Cambios guardados. Se cerraron las sesiones anteriores de esta cuenta.';if(account.value.id===props.viewer.id)sessionEnded.value=true;}
});}
function ask(action){pending.value=action;error.value='';confirmDialog.value.showModal();}
async function access(){await run(async()=>{const data=await adminRequest(`/api/usuarios/${account.value.id}/acceso`,{method:'POST',body:JSON.stringify({action:pending.value})});confirmDialog.value.close();if(data.setupToken)showLink(account.value.id,data.setupToken);notice.value=pending.value==='reset'?'Acceso restablecido. El nuevo enlace vence en una hora.':'Todas las sesiones de esta cuenta se cerraron.';if(account.value.id===props.viewer.id){sessionEnded.value=true;}else{const updated=(await adminRequest('/api/usuarios')).users.find(u=>u.id===account.value.id);if(updated){account.value=updated;form.value.version=updated.authVersion;}}});}
async function copy(){try{await navigator.clipboard.writeText(setupLink.value);notice.value='Enlace copiado.';}catch{notice.value='Selecciona el enlace para copiarlo manualmente.';}}
</script>
<template><section class="editorial-workspace account-workspace">
<nav class="record-breadcrumb" aria-label="Ruta de navegación"><a href="/admin/usuarios">← Cuentas y permisos</a><span aria-hidden="true">/</span><span>{{isNew?'Nueva cuenta':account.name}}</span></nav>
<form @submit.prevent="save">
<div class="workspace-heading"><div><p class="eyebrow">{{isNew?'AMPLÍA TU EQUIPO':'REGISTRO DE CUENTA'}}</p><h1>{{isNew?'Invitar persona':account.name}}</h1><p class="subtle">{{isNew?'Prepara sus accesos y envíale un enlace para activar su cuenta.':'Gestiona su información y define dónde puede trabajar.'}}</p></div><div class="record-actions"><a class="ui-button" href="/admin/usuarios">Volver al listado</a><button class="ui-button primary" :disabled="busy||sessionEnded||(!isNew&&!dirty)">{{busy?'Guardando…':isNew?'Crear invitación':'Guardar cambios'}}</button></div></div>
<p v-if="error" class="ui-alert error" role="alert">{{error}}</p><p v-if="notice" class="ui-alert" role="status">{{notice}}</p><p v-if="sessionEnded" class="ui-alert">Tu sesión anterior quedó cerrada. <a class="link" href="/login">Volver a iniciar sesión</a>.</p>
<div v-if="setupLink" class="private-link-card workspace-sheet"><div><p class="eyebrow">ENLACE PRIVADO DE ACTIVACIÓN</p><h2>{{isNew?'Completar registro':'Establecer contraseña'}}</h2><p class="subtle">Este enlace solo se muestra en esta pantalla. Compártelo directamente con la persona.</p></div><label class="field-label">Enlace de acceso<input class="ui-control" readonly :value="setupLink" @focus="$event.target.select()" /></label><div class="record-actions"><button type="button" class="ui-button" @click="copy">Copiar enlace</button><button type="button" class="ui-button quiet" @click="setupLink=''">Ocultar</button></div></div>
<div class="record-layout account-layout"><div class="account-sections">
<section class="workspace-sheet form-sheet"><div class="section-heading"><span class="section-number">01</span><div><h2>Datos de la persona</h2><p class="subtle">Cada cuenta es individual y tiene su propio acceso.</p></div></div><fieldset class="form-grid" :disabled="busy||sessionEnded"><label class="field-label">Nombre completo<input v-model="form.name" class="ui-control" required minlength="2" maxlength="120" autocomplete="name" placeholder="Nombre y apellido" /></label><label class="field-label">Correo electrónico<input v-model="form.email" class="ui-control" type="email" required autocomplete="email" :disabled="!isNew" placeholder="nombre@institucion.edu.sv" /><span v-if="!isNew" class="field-help">El correo identifica esta cuenta y no se modifica aquí.</span></label><label v-if="!isNew" class="field-label">Estado de la cuenta<select v-model="form.status" class="ui-control"><option v-if="account.status==='invited'" value="invited">Invitación pendiente</option><option v-else value="active">Activa</option><option value="disabled">Desactivada</option></select></label></fieldset></section>
<section class="workspace-sheet form-sheet"><div class="section-heading"><span class="section-number">02</span><div><h2>Roles y permisos</h2><p class="subtle">Cada rol tiene sus propios módulos y secciones asignados.</p></div></div>
<fieldset v-for="(assignment,index) in form.assignments" :key="index" class="assignment-card" :disabled="busy||sessionEnded"><legend>Asignación {{index+1}}</legend><div class="assignment-heading"><label class="field-label">Rol<select v-model="assignment.role" class="ui-control" @change="changeRole(assignment)"><option v-for="(label,key) in ROLE_LABELS" :key="key" :value="key">{{label}}</option></select></label><button type="button" class="ui-button quiet danger-text" :disabled="form.assignments.length===1" @click="form.assignments.splice(index,1)" :aria-label="`Quitar asignación ${index+1}`">Quitar rol</button></div><p class="role-explanation">{{ROLE_DESCRIPTIONS[assignment.role]}}</p>
<template v-if="assignment.role!=='administrador'"><p class="field-group-title">Módulos con acceso</p><div class="permission-options"><label v-for="module in MODULES" :key="module" class="permission-option"><input v-model="assignment.modules" type="checkbox" class="checkbox checkbox-sm" :value="module" /><span>{{MODULE_LABELS[module]}}</span></label></div><template v-if="assignment.modules.includes('gaceta')"><p class="field-group-title">Secciones de Gaceta</p><div class="permission-options"><label class="permission-option"><input type="checkbox" class="checkbox checkbox-sm" :checked="assignment.sections.includes('*')" @change="toggleAll(assignment,$event)" /><span>Todas las secciones</span></label><label v-for="section in SECTIONS" :key="section" class="permission-option"><input v-model="assignment.sections" type="checkbox" class="checkbox checkbox-sm" :value="section" @change="selectSection(assignment)" /><span>{{NEWS_SECTIONS[section]}}</span></label></div></template></template></fieldset>
<button type="button" class="ui-button add-assignment" :disabled="busy||sessionEnded||form.assignments.length>=12" @click="form.assignments.push({role:'consulta',modules:[],sections:[]})">＋ Agregar otro rol y alcance</button><p class="field-help">Los módulos auxiliares (inicio, autores e investigadores) se administran con el rol Director editorial.</p></section>
<section v-if="!isNew" class="workspace-sheet form-sheet"><div class="section-heading"><span class="section-number">03</span><div><h2>Seguridad y acceso</h2><p class="subtle">Estas acciones se aplican a todas las sesiones de esta cuenta.</p></div></div><div class="security-action"><div><h3>Cerrar sesiones</h3><p class="subtle">La persona deberá iniciar sesión de nuevo con su contraseña actual.</p></div><button class="ui-button" type="button" :disabled="busy||sessionEnded" @click="ask('revoke')">Cerrar sesiones</button></div><div class="security-action"><div><h3>Restablecer acceso</h3><p class="subtle">Invalida su contraseña y genera un enlace privado que vence en una hora.</p></div><button class="ui-button" type="button" :disabled="busy||sessionEnded" @click="ask('reset')">Restablecer acceso</button></div></section>
</div><aside class="record-sidebar"><div class="workspace-sheet side-card account-summary"><span class="profile-avatar" aria-hidden="true">{{initials(form.name)||'+'}}</span><h2>{{form.name||'Nueva persona'}}</h2><p class="subtle">{{form.email||'Correo de acceso'}}</p><span class="state-badge" :data-state="form.status">{{ACCOUNT_STATES[form.status]}}</span><dl><div><dt>Roles asignados</dt><dd>{{form.assignments.length}}</dd></div><div><dt>Módulos editoriales</dt><dd>{{moduleCount}}</dd></div><div v-if="account"><dt>Cuenta creada</dt><dd>{{dateLabel(account.createdAt)}}</dd></div></dl></div><div class="workspace-sheet side-card"><h2>Antes de guardar</h2><p class="subtle">{{isNew?'La persona establecerá su contraseña desde el enlace de invitación. Vence en 24 horas.':'Guardar cambios revoca las sesiones de esta cuenta para aplicar los nuevos permisos.'}}</p><p v-if="account?.id===viewer.id" class="field-help">Estás modificando tu propia cuenta.</p></div></aside></div>
<div class="record-savebar"><span class="subtle">{{dirty?'Tienes cambios sin guardar.':'Los datos están actualizados.'}}</span><button class="ui-button primary" :disabled="busy||sessionEnded||(!isNew&&!dirty)">{{busy?'Guardando…':isNew?'Crear invitación':'Guardar cambios'}}</button></div></form>
<dialog ref="confirmDialog" class="modal editorial-modal" aria-labelledby="account-action-title" @cancel="busy&&$event.preventDefault()"><form class="modal-box ui-dialog" @submit.prevent="access"><p class="eyebrow">SEGURIDAD DE LA CUENTA</p><h2 id="account-action-title">{{pending==='reset'?'Restablecer acceso':'Cerrar sesiones'}}</h2><p class="subtle">{{pending==='reset'?'Se invalidará la contraseña actual y se cerrarán todas sus sesiones. Se generará un nuevo enlace privado.':'Se cerrarán todas las sesiones de esta persona. Podrá volver a ingresar con su contraseña actual.'}}</p><p class="dialog-record-title">{{account?.name}}</p><p v-if="error" class="ui-alert error" role="alert">{{error}}</p><div class="dialog-actions"><button type="button" class="ui-button" :disabled="busy" @click="confirmDialog.close()">Cancelar</button><button class="ui-button primary" :disabled="busy">{{busy?'Procesando…':'Confirmar'}}</button></div></form></dialog>
</section></template>
